import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;class ContractTest{static String capture(Runnable action){PrintStream previous=System.out;ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(PrintStream out=new PrintStream(bytes,true,StandardCharsets.UTF_8)){System.setOut(out);action.run();}finally{System.setOut(previous);}return bytes.toString(StandardCharsets.UTF_8).replace("\r\n","\n");}@Test void exactOrderDuplicatesAndState(){Object a=TaskBinding.car(1,"A","M",2000,10),b=TaskBinding.car(2,"A","m",2001,11);Object[]in=TaskBinding.array(a,b,a);String sa=TaskBinding.state(a),sb=TaskBinding.state(b);assertValues(new Object[]{a,a},select(in,()->TaskBinding.older(in,"M",2025,24)));assertValues(new Object[]{a,b,a},select(in,()->TaskBinding.make(in,"A")));assertValues(new Object[0],select(in,()->TaskBinding.make(in,"a")));assertValues(new Object[]{b},select(in,()->TaskBinding.dearer(in,2001,10)));assertValues(new Object[0],TaskBinding.dearer(TaskBinding.array(),1,0));assertValues(new Object[]{a,b,a},in);assertEquals(sa,TaskBinding.state(a));assertEquals(sb,TaskBinding.state(b));} @Test void twoConstructorsAndProperties(){Object c=TaskBinding.shortCar();assertFalse(TaskBinding.text(c).isBlank());TaskBinding.edit(c);assertEquals("7|B|N|2025|blue|3.0|Y",TaskBinding.state(c));}static void assertValues(Object[]expected,Object[]actual){assertNotNull(actual,"подборка");assertEquals(java.util.Arrays.stream(expected).map(TaskBinding::value).toList(),java.util.Arrays.stream(actual).map(TaskBinding::value).toList(),"значения, порядок и кратность подборки; identity результата свободна");}static Object[] select(Object[]input,java.util.function.Supplier<Object[]>action){Object[]before=input.clone();var states=java.util.Arrays.stream(before).map(TaskBinding::value).toList();Object[]result=action.get();assertEquals(before.length,input.length);for(int i=0;i<before.length;i++)assertSame(before[i],input[i],"селектор изменил ячейку переданного typed массива, index="+i);assertEquals(states,java.util.Arrays.stream(input).map(TaskBinding::value).toList(),"селектор изменил поля исходных объектов");return result;}}
